// VALIDAR ENTRADA BÁSICA
// No registra ni devuelve el JWT, tokens ni el contenido del mensaje.
// El nodo Webhook solo acepta POST; la query string se ignora por diseño.
const req = $('Workvivo Chatbot Callback').first().json;
const headers = {};
for (const [k, v] of Object.entries(req.headers || {})) headers[String(k).toLowerCase()] = Array.isArray(v) ? v[0] : v;

const correlationId = 'wv-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
const CFG = $('Configuración').first().json;
const env = (k, d = '') => { const v = CFG[k]; return v === undefined || v === null || String(v).trim() === '' ? d : String(v).trim(); };
let jwtDiag = '';
const reject = (httpStatus, category) => [{ json: { ok: false, correlationId, httpStatus, category, stage: 'entrada', detail: jwtDiag } }];

// 1) Configuración (nodo "Configuración"): si falta un valor obligatorio se rechaza (fail closed).
// Solo lo necesario para recibir de Workvivo. La config de Validator se comprueba antes de llamarlo.
const REQUIRED = ['WORKVIVO_API_BASE_URL', 'WORKVIVO_ID', 'DATASTORE_NAMESPACE'];
const missing = REQUIRED.filter((k) => !env(k));
if (missing.length) return reject(503, 'CONFIG_INCOMPLETA');

// 2) HTTPS obligatorio (el proxy inverso informa el esquema original).
const proto = String(headers['x-forwarded-proto'] || '').split(',')[0].trim().toLowerCase();
if (proto !== 'https') return reject(403, 'HTTPS_REQUERIDO');

// 3) Content-Type
const ct = String(headers['content-type'] || '').toLowerCase();
if (!ct.startsWith('application/json')) return reject(415, 'CONTENT_TYPE_INVALIDO');

// 4) Tamaño
const maxBytes = Number(env('MAX_REQUEST_BYTES', '262144'));
const declared = Number(headers['content-length'] || 0);
const body = req.body;
if (!body || typeof body !== 'object' || Array.isArray(body) || Object.keys(body).length === 0) return reject(400, 'BODY_VACIO');
const actual = Buffer.byteLength(JSON.stringify(body), 'utf8');
if (declared > maxBytes || actual > maxBytes) return reject(413, 'PAYLOAD_DEMASIADO_GRANDE');

// 5) JWT presente y bien formado (tres segmentos, firma no vacía)
const jwt = headers['x-workvivo-jwt'];
if (typeof jwt !== 'string' || !jwt) return reject(401, 'JWT_AUSENTE');
if (jwt.length > 8192 || !/^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(jwt)) return reject(401, 'JWT_MAL_FORMADO');

// 6) Allowlist de algoritmos (defensa previa; la verificación real la hace el nodo JWT con la clave fijada)
let jwtHeader;
try { jwtHeader = JSON.parse(Buffer.from(jwt.split('.')[0], 'base64url').toString('utf8')); } catch (e) { return reject(401, 'JWT_MAL_FORMADO'); }
// Diagnóstico SIN secretos (datos públicos del token, nunca el token): ayuda a obtener la clave y los claims oficiales.
try {
  const p = JSON.parse(Buffer.from(jwt.split('.')[1], 'base64url').toString('utf8'));
  jwtDiag = `alg=${jwtHeader.alg || ''}; kid=${jwtHeader.kid || ''}; claims=${Object.keys(p).sort().join(',')}; iss=${p.iss || ''}; aud=${JSON.stringify(p.aud || '')}; publicKeyUrl=${p.publicKeyUrl || ''}`.slice(0, 500);
} catch (e) { jwtDiag = `alg=${jwtHeader.alg || ''}; kid=${jwtHeader.kid || ''}; payload no legible`; }
const allowedAlgs = env('WORKVIVO_JWT_ALGORITHMS', 'RS256').split(',').map((s) => s.trim()).filter(Boolean);
const alg = String(jwtHeader && jwtHeader.alg || '');
if (!alg || alg.toLowerCase() === 'none' || !allowedAlgs.includes(alg)) return reject(401, 'JWT_ALG_NO_PERMITIDO');

// 6b) Endpoint del agente solo por HTTPS
if (!/^https:\/\//i.test(env('WORKVIVO_API_BASE_URL'))) return reject(503, 'CONFIG_URL_NO_HTTPS');

// 7) Campos mínimos. Según el ejemplo de referencia de Workvivo, cada evento trae "category" o "action".
// PENDIENTE DE DOCUMENTACIÓN: confirmar con el payload oficial.
if (!body.category && !body.action) return reject(400, 'PAYLOAD_SIN_TIPO_DE_EVENTO');

return [{ json: { ok: true, correlationId, jwt, body, jwtDiag } }];

// VALIDAR CLAIMS JWT
// La firma, el algoritmo, exp y nbf ya fueron verificados criptográficamente por el nodo
// "Validar firma JWT (Workvivo)" con la clave pública fijada en su credencial.
// Aquí se comprueban issuer, audience, aplicación/tenant y antigüedad.
// Valor especial "NO_APLICA": desactiva explícitamente un claim que Workvivo no emite (nunca en silencio).
const claims = $input.first().json || {};
const base = $('Validar entrada básica').first().json;
const CFG = $('Configuración').first().json;
const env = (k, d = '') => { const v = CFG[k]; return v === undefined || v === null || String(v).trim() === '' ? d : String(v).trim(); };
const now = Math.floor(Date.now() / 1000);
const claimKeys = Object.keys(claims).sort().join(',');
const fail = (httpStatus, category, withDiag = false) => [{ json: {
  jwtValid: false, correlationId: base.correlationId, httpStatus, category, stage: 'jwt',
  // Diagnóstico sin secretos: nombres de claims y valores públicos iss/aud, útil para completar la configuración.
  detail: withDiag ? `claims=${claimKeys}; iss=${String(claims.iss || '')}; aud=${JSON.stringify(claims.aud || '')}` : '',
} }];

if (typeof claims.exp !== 'number') return fail(401, 'JWT_SIN_EXP', true);
if (claims.exp < now - 30) return fail(401, 'JWT_EXPIRADO');
if (typeof claims.nbf === 'number' && claims.nbf > now + 30) return fail(401, 'JWT_NBF');
const maxAge = Number(env('JWT_MAX_AGE_SECONDS', '300'));
if (typeof claims.iat === 'number' && (now - claims.iat > maxAge || claims.iat > now + 60)) return fail(401, 'JWT_FUERA_DE_VENTANA');

const expIss = env('WORKVIVO_EXPECTED_ISSUER');
if (!expIss) return fail(503, 'CONFIG_ISSUER_PENDIENTE', true);
if (expIss !== 'NO_APLICA' && claims.iss !== expIss) return fail(403, 'JWT_ISSUER_INVALIDO', true);

const expAud = env('WORKVIVO_EXPECTED_AUDIENCE');
if (!expAud) return fail(503, 'CONFIG_AUDIENCE_PENDIENTE', true);
const auds = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
if (expAud !== 'NO_APLICA' && !auds.includes(expAud)) return fail(403, 'JWT_AUDIENCE_INVALIDO', true);

// Aplicación: el nombre del claim se configura en WORKVIVO_APP_ID_CLAIM (PENDIENTE DE DOCUMENTACIÓN).
const expApp = env('WORKVIVO_APP_ID');
if (!expApp) return fail(503, 'CONFIG_APP_ID_PENDIENTE', true);
if (expApp !== 'NO_APLICA') {
  const appClaim = env('WORKVIVO_APP_ID_CLAIM');
  if (!appClaim) return fail(503, 'CONFIG_APP_ID_CLAIM_PENDIENTE', true);
  if (String(claims[appClaim] ?? '') !== expApp) return fail(403, 'JWT_APP_INVALIDA', true);
}

// Tenant (opcional): si se define WORKVIVO_TENANT_CLAIM, su valor debe coincidir con WORKVIVO_ID.
const tenantClaim = env('WORKVIVO_TENANT_CLAIM');
if (tenantClaim && String(claims[tenantClaim] ?? '') !== env('WORKVIVO_ID')) return fail(403, 'JWT_TENANT_INVALIDO', true);

// El ejemplo de referencia incluye "publicKeyUrl" en el payload. Nunca se usa para obtener claves
// (la clave está fijada en la credencial); si viene, debe coincidir con la URL oficial configurada.
const jwksUrl = env('WORKVIVO_JWKS_URL');
if (claims.publicKeyUrl && jwksUrl && claims.publicKeyUrl !== jwksUrl) return fail(403, 'JWT_ORIGEN_DE_CLAVE_INESPERADO', true);

return [{ json: { jwtValid: true, correlationId: base.correlationId, jti: claims.jti ? String(claims.jti) : null } }];

// NORMALIZAR EVENTO WORKVIVO
// Mapeo tomado del ejemplo de referencia publicado por Workvivo/Zoom
// (github.com/Yosuke-workvivo/Workvivo-Chatbot). Los campos con [] son
// PENDIENTE DE DOCUMENTACIÓN: complétalos con las rutas del payload oficial
// (developer.workvivo.com -> Chat -> Bots) o de un evento real de pruebas. No se adivinan.
const MAP = {
  category:        ['category'],            // 'bot_message_notification' = mensaje de un usuario al bot
  action:          ['action'],              // 'chat_bot_message_sent'    = mensaje enviado por el bot
  botUserId:       ['bot.bot_userid'],
  chatId:          ['channel.channel_url'],
  text:            ['message.text'],
  eventId:         [],  // PENDIENTE DE DOCUMENTACIÓN
  messageId:       [],  // PENDIENTE DE DOCUMENTACIÓN
  threadId:        [],  // PENDIENTE DE DOCUMENTACIÓN
  userId:          [],  // PENDIENTE DE DOCUMENTACIÓN (remitente)
  userDisplayName: [],  // PENDIENTE DE DOCUMENTACIÓN
  mentions:        [],  // PENDIENTE DE DOCUMENTACIÓN
  attachments:     [],  // PENDIENTE DE DOCUMENTACIÓN (lista de adjuntos)
};
// Rutas dentro de cada adjunto. PENDIENTE DE DOCUMENTACIÓN.
const ATTACHMENT_MAP = { url: [], name: [], mimeType: [], size: [] };
// El contrato del canal API de Validator no está documentado todavía: ningún archivo se envía.
const VALIDATOR_ACCEPTS_FILES = false; // PENDIENTE DE DOCUMENTACIÓN
const VALIDATOR_FILE_TYPES = [];        // PENDIENTE DE DOCUMENTACIÓN (MIME admitidos por el canal API)

const base = $('Validar entrada básica').first().json;
const jwtInfo = $input.first().json;
const b = base.body || {};
const CFG = $('Configuración').first().json;
const env = (k, d = '') => { const v = CFG[k]; return v === undefined || v === null || String(v).trim() === '' ? d : String(v).trim(); };
const get = (o, p) => p.split('.').reduce((a, k) => (a !== undefined && a !== null ? a[k] : undefined), o);
const pickFrom = (o, paths) => { for (const p of paths) { const v = get(o, p); if (v !== undefined && v !== null && String(v).trim() !== '') return v; } return null; };
const pick = (k) => pickFrom(b, MAP[k]);
const str = (v) => (v === null || v === undefined ? '' : String(v));

const ns = env('DATASTORE_NAMESPACE');
const tenantId = env('WORKVIVO_ID');
const ev = {
  correlationId: base.correlationId,
  eventId: str(pick('eventId')),
  tenantId,
  botId: str(pick('botUserId')),
  chatId: str(pick('chatId')),
  threadId: str(pick('threadId')),
  userId: str(pick('userId')),
  userDisplayName: str(pick('userDisplayName')),
  messageId: str(pick('messageId')),
  text: str(pick('text')).trim(),
  mentions: Array.isArray(pick('mentions')) ? pick('mentions') : [],
  attachments: [],
  receivedAt: new Date().toISOString(),
};
const category = str(pick('category'));
const action = str(pick('action'));

// ---- Adjuntos: política anti-SSRF y de tipos. No se descarga nada mientras el contrato esté pendiente.
const allowedHosts = env('ALLOWED_ATTACHMENT_HOSTS').split(',').map((h) => h.trim().toLowerCase()).filter(Boolean);
const maxAtt = Number(env('MAX_ATTACHMENT_BYTES', '10485760'));
const BLOCKED_EXT = /\.(exe|dll|bat|cmd|com|msi|scr|ps1|vbs|js|jar|sh|app|dmg|iso|apk|html?|svg|zip|rar|7z)$/i;
const rawAtt = Array.isArray(pick('attachments')) ? pick('attachments') : [];
for (const a of rawAtt.slice(0, 10)) {
  const url = str(pickFrom(a, ATTACHMENT_MAP.url));
  const name = str(pickFrom(a, ATTACHMENT_MAP.name)).slice(0, 200) || 'archivo';
  const mime = str(pickFrom(a, ATTACHMENT_MAP.mimeType)).toLowerCase();
  const size = Number(pickFrom(a, ATTACHMENT_MAP.size) || 0);
  let status = 'no_soportado', reason = 'CANAL_VALIDATOR_SIN_SOPORTE_DE_ARCHIVOS';
  let u = null; try { u = new URL(url); } catch (e) {}
  const host = u ? u.hostname.toLowerCase() : '';
  if (!u || u.protocol !== 'https:' || u.username || u.password) { status = 'rechazado'; reason = 'URL_NO_PERMITIDA'; }
  else if (/^[\d.]+$/.test(host) || host.includes(':') || host === 'localhost') { status = 'rechazado'; reason = 'HOST_IP_NO_PERMITIDO'; }
  else if (!allowedHosts.some((h) => host === h || host.endsWith('.' + h))) { status = 'rechazado'; reason = 'HOST_NO_AUTORIZADO'; }
  else if (BLOCKED_EXT.test(name)) { status = 'rechazado'; reason = 'TIPO_PELIGROSO'; }
  else if (size > maxAtt) { status = 'rechazado'; reason = 'ARCHIVO_DEMASIADO_GRANDE'; }
  else if (VALIDATOR_ACCEPTS_FILES && VALIDATOR_FILE_TYPES.includes(mime)) { status = 'compatible'; reason = ''; }
  ev.attachments.push({ name, mimeType: mime, size, status, reason }); // la URL no sale de este nodo
}

// ---- Decisión de ruta
let route = 'procesar', httpStatus = 200, reason = '';
if (action === 'chat_bot_message_sent') { route = 'ignorar'; reason = 'EVENTO_DEL_PROPIO_BOT'; }
else if (category !== 'bot_message_notification') { route = 'ignorar'; reason = 'EVENTO_NO_SOPORTADO'; }
else if (ev.userId && ev.botId && ev.userId === ev.botId) { route = 'ignorar'; reason = 'MENSAJE_PROPIO_BOT'; }
else if (!ev.chatId || !ev.botId) { route = 'rechazar'; httpStatus = 400; reason = 'PAYLOAD_INCOMPLETO'; }

// Clave de conversación estable (un canal de bot en Workvivo es 1:1 usuario-bot).
const convKey = `${ns}:${tenantId}:${ev.chatId}:${ev.userId || 'sin-user-id'}`;

// Rate limit por conversación (ventana de 60 s, en memoria del workflow de producción).
if (route === 'procesar') {
  const limit = Number(env('RATE_LIMIT_PER_MINUTE', '10'));
  const sd = $getWorkflowStaticData('global');
  sd.rl = sd.rl || {};
  const nowMs = Date.now();
  for (const k of Object.keys(sd.rl)) if (nowMs - sd.rl[k].t > 60000) delete sd.rl[k];
  const rl = sd.rl[convKey] || { t: nowMs, n: 0 };
  rl.n += 1; sd.rl[convKey] = rl;
  if (rl.n > limit) { route = 'rechazar'; httpStatus = 429; reason = 'RATE_LIMIT'; }
}

// Idempotencia: eventId > messageId > jti del JWT. Sin ninguno, no se puede deduplicar (queda marcado).
const idPart = ev.eventId ? 'evt:' + ev.eventId : ev.messageId ? 'msg:' + ev.messageId : jwtInfo.jti ? 'jti:' + jwtInfo.jti : '';
const dedupeKey = idPart ? `${ns}:${tenantId}:${idPart}` : `${ns}:sin-id:${ev.correlationId}`;

return [{ json: { ...ev, route, httpStatus, category: reason, stage: 'evento', convKey, dedupeKey, dedupeAvailable: !!idPart } }];

// PREPARAR SOLICITUD PARA VALIDATOR
// n8n no genera diagnósticos: si no hay texto ni archivo compatible, se envía igualmente
// una solicitud válida (sin inventar contenido) para que Validator aplique su propia regla.
// No se envían: token/JWT de Workvivo, headers, nombre del usuario ni logs técnicos.
const ev = $('Normalizar evento Workvivo').first().json;
const row = $input.first().json || {};
const CFG = $('Configuración').first().json;
const env = (k, d = '') => { const v = CFG[k]; return v === undefined || v === null || String(v).trim() === '' ? d : String(v).trim(); };

const conversationId = row.validatorConversationId ? String(row.validatorConversationId) : null;
const compatibles = ev.attachments.filter((a) => a.status === 'compatible');
const noAnalizados = ev.attachments.filter((a) => a.status !== 'compatible').map((a) => a.name);
const hasReviewableInput = !!ev.text || compatibles.length > 0;

// ============ PENDIENTE DE DOCUMENTACIÓN ============
// Esquema oficial de solicitud del canal API del agente (Agent Builder -> canal API, id "agtch_...").
// Sustituye los NOMBRES de campo de este objeto por los del contrato oficial. Los valores ya son correctos.
const validatorBody = {
  channel_id: env('CHATGPT_AGENT_CHANNEL_ID'), // PENDIENTE: puede ir en la URL en lugar del body
  input: ev.text,                               // PENDIENTE: nombre del campo de mensaje
  conversation_id: conversationId,              // PENDIENTE: continuidad de conversación
  metadata: {                                   // PENDIENTE: solo si el contrato admite metadatos
    correlation_id: ev.correlationId,
    source: 'workvivo',
    has_reviewable_input: hasReviewableInput,
    attachments_not_analyzed: noAnalizados,
  },
};
// =====================================================

const configOk = /^https:\/\//i.test(env('CHATGPT_AGENT_API_URL')) && !!env('CHATGPT_AGENT_CHANNEL_ID');
if (!configOk) return [{ json: { configOk, route: 'error', correlationId: ev.correlationId, category: 'CONFIG_VALIDATOR_PENDIENTE', node: 'Preparar solicitud Validator', httpStatus: 0 } }];
return [{ json: { configOk, correlationId: ev.correlationId, idempotencyKey: ev.dedupeKey, validatorBody, noAnalizados } }];

// EVALUAR RESPUESTA DE VALIDATOR: reintentos con backoff exponencial, 429 (Retry-After), 4xx y 5xx.
// $runIndex cuenta cuántas veces se ha ejecutado este nodo en la ejecución = número de intento - 1.
const r = $input.first().json || {};
const prep = $('Preparar solicitud Validator').first().json;
const CFG = $('Configuración').first().json;
const env = (k, d = '') => { const v = CFG[k]; return v === undefined || v === null || String(v).trim() === '' ? d : String(v).trim(); };
const maxRetries = Number(env('VALIDATOR_MAX_RETRIES', '3'));
const attempt = $runIndex;

let status = Number(r.statusCode || 0);
let category = '', retryable = false;
if (r.error || !status) {
  const msg = String((r.error && (r.error.message || r.error.code || r.error)) || '').toLowerCase();
  category = /timeout|timedout|econnaborted|etimedout/.test(msg) ? 'VALIDATOR_TIMEOUT' : 'VALIDATOR_RED';
  retryable = true;
} else if (status >= 200 && status < 300) {
  return [{ json: { route: 'ok', correlationId: prep.correlationId, statusCode: status, body: r.body } }];
} else if (status === 429) { category = 'VALIDATOR_429'; retryable = true; }
else if (status === 408 || status >= 500) { category = 'VALIDATOR_5XX'; retryable = true; }
else { category = 'VALIDATOR_4XX'; retryable = false; }

if (retryable && attempt < maxRetries) {
  const hdr = r.headers || {};
  const ra = Number(hdr['retry-after'] || hdr['Retry-After'] || 0);
  const backoff = Math.min(2 ** attempt * 2, 30) + Math.random();
  const waitSeconds = Math.min(ra > 0 ? ra : backoff, 30);
  return [{ json: { route: 'reintentar', correlationId: prep.correlationId, attempt: attempt + 1, waitSeconds, category } }];
}
return [{ json: { route: 'error', correlationId: prep.correlationId, category, httpStatus: status, node: 'Enviar a Validator' } }];

// EXTRAER RESPUESTA DE VALIDATOR
// Solo el texto final visible para el usuario. Nunca razonamiento, trazas ni metadatos técnicos.
// PENDIENTE DE DOCUMENTACIÓN: rutas del esquema oficial de respuesta del canal API. Se configuran con
// VALIDATOR_RESPONSE_TEXT_PATH y VALIDATOR_RESPONSE_CONVERSATION_PATH (notación con puntos, p. ej. "a.b.0.c").
// Si la API es asíncrona (devuelve un "run" en curso), hace falta un paso adicional: ver README.
const r = $input.first().json;
const ev = $('Normalizar evento Workvivo').first().json;
const prep = $('Preparar solicitud Validator').first().json;
const CFG = $('Configuración').first().json;
const env = (k, d = '') => { const v = CFG[k]; return v === undefined || v === null || String(v).trim() === '' ? d : String(v).trim(); };
const get = (o, p) => p.split('.').reduce((a, k) => (a !== undefined && a !== null ? a[k] : undefined), o);

const textPath = env('VALIDATOR_RESPONSE_TEXT_PATH');
const convPath = env('VALIDATOR_RESPONSE_CONVERSATION_PATH');
const err = (category) => [{ json: { route: 'error', correlationId: ev.correlationId, category, httpStatus: r.statusCode || 0, node: 'Extraer respuesta de Validator' } }];
if (!textPath) return err('VALIDATOR_ESQUEMA_PENDIENTE');

let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { return err('VALIDATOR_RESPUESTA_NO_JSON'); } }
const text = get(body, textPath);
if (typeof text !== 'string' || !text.trim()) return err('VALIDATOR_SIN_TEXTO_FINAL');

let replyText = text.trim();
if (prep.noAnalizados && prep.noAnalizados.length) {
  replyText += `\n\nNota: no pude analizar ${prep.noAnalizados.length === 1 ? 'este archivo' : 'estos archivos'} porque el canal de Validator no los admite: ${prep.noAnalizados.join(', ')}.`;
}
const newConv = convPath ? get(body, convPath) : null;

return [{ json: {
  route: 'ok', correlationId: ev.correlationId, replyText,
  validatorConversationId: newConv ? String(newConv) : '',
  convKey: ev.convKey, botUserId: ev.botId, chatId: ev.chatId,
} }];

// PREPARAR ERROR: registra nodo, código HTTP y categoría. Sin secretos ni trazas.
// Decide si corresponde avisar al usuario con un mensaje neutral.
const j = $input.first().json || {};
const ev = $('Normalizar evento Workvivo').first().json;
let category = j.category, node = j.node, httpStatus = Number(j.httpStatus || 0);
if (!category) {
  // Salida de error del nodo "Responder en Workvivo"
  category = 'WORKVIVO_API';
  node = 'Responder en Workvivo';
  const m = String((j.error && (j.error.message || j.error)) || '').match(/\b([45]\d\d)\b/);
  httpStatus = m ? Number(m[1]) : 0;
}
// Si falló la propia API de Workvivo, un aviso por la misma API también fallaría.
const notifyUser = category !== 'WORKVIVO_API';
return [{ json: {
  correlationId: ev.correlationId, stage: 'procesamiento', category, node: node || '', httpStatus,
  notifyUser, botUserId: ev.botId, chatId: ev.chatId,
} }];

// PREPARAR RECHAZO: unifica los rechazos (entrada, firma JWT, claims, payload, rate limit).
// Solo se conserva correlationId, código HTTP y categoría general. Nunca el JWT ni el contenido.
const j = $input.first().json || {};
let base = {};
try { base = $('Validar entrada básica').first().json; } catch (e) {}
const correlationId = j.correlationId || base.correlationId || ('wv-' + Date.now().toString(36));
let httpStatus = j.httpStatus;
let category = j.category;
let stage = j.stage || 'jwt';

if (!category) {
  // Viene de la salida de error del nodo JWT (firma, expiración, nbf o algoritmo).
  const msg = String((j.error && (j.error.message || j.error)) || j.message || '').toLowerCase();
  httpStatus = 401;
  if (msg.includes('expired')) category = 'JWT_EXPIRADO';
  else if (msg.includes('not active')) category = 'JWT_NBF';
  else if (msg.includes('algorithm')) category = 'JWT_ALG_NO_PERMITIDO';
  else category = 'JWT_FIRMA_INVALIDA';
}

return [{ json: { correlationId, httpStatus: Number(httpStatus) || 400, category, stage, detail: String(j.detail || (stage === 'jwt' ? base.jwtDiag : '') || '').slice(0, 500) } }];
